-- 0001_initial_schema.sql — Edgeplane initial schema
--
-- This file is the squashed result of 12 incremental migrations from the
-- upstream MissionControl repo (0001 through 0012). The squash captures
-- the schema state at the post-Domain/Mission/Task rename baseline that
-- edgeplane forked from.
--
-- Generated by: pg_dump --schema-only against a fresh DB after applying
-- the 12 incremental migrations in order. Verified against the equivalent
-- 67-table / 772-column shape produced by the incremental path.
--
-- Fresh deployments apply only this file. No additional migrations are
-- needed until the project introduces a new schema change post-fork.

--

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

SET default_tablespace = '';

SET default_table_access_method = heap;

